import{_ as a,o,c as t,a5 as r}from"./chunks/framework.DOB-AMqW.js";const p=JSON.parse('{"title":"AR Blogz Privacy Policy","description":"Official Privacy Policy for AR Blogz.","frontmatter":{"title":"AR Blogz Privacy Policy","description":"Official Privacy Policy for AR Blogz.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/arblogz.md","filePath":"privacy/arblogz.md"}'),i={name:"privacy/arblogz.md"};function n(s,e,l,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy-for-ar-blogz" tabindex="-1">Privacy Policy for AR Blogz <a class="header-anchor" href="#privacy-policy-for-ar-blogz" aria-label="Permalink to &quot;Privacy Policy for AR Blogz&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>AR Blogz is a personal, multilingual blog published by <strong>Anand Raja</strong>. It provides articles, short feed updates, archives, search, RSS, media embeds, contact options, and optional donation links.</p><p>AR Blogz does not currently offer reader accounts or a newsletter. Site analytics and public comments are currently disabled in the reviewed configuration.</p><h2 id="information-you-submit" tabindex="-1">Information You Submit <a class="header-anchor" href="#information-you-submit" aria-label="Permalink to &quot;Information You Submit&quot;">​</a></h2><p>The contact form asks for your name, email address, optional phone number, inquiry purpose, and message. When you submit it, those fields are sent directly to a configured Google Form and are available to Google and the form owner. AR Blogz uses the information to read and respond to your inquiry, review corrections or suggestions, and manage collaboration or privacy requests.</p><p>Do not submit passwords, financial credentials, sensitive health information, or information you are not authorized to share. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><p>Comments are disabled. If comments are enabled in the future, this policy must be updated before collecting comment details through Giscus or Waline.</p><h2 id="browser-storage" tabindex="-1">Browser Storage <a class="header-anchor" href="#browser-storage" aria-label="Permalink to &quot;Browser Storage&quot;">​</a></h2><p>AR Blogz stores your selected theme and interface language in localStorage. If a password-protected article is used and you unlock it, the site stores a local access record containing the configured password hash and timestamp for up to 24 hours. The plain-text password is not stored or sent to an AR Blogz server. This client-side control is not a reader account or strong protection against someone who can inspect the delivered site files.</p><p>These local records remain until they expire, are replaced, or you clear browser site data.</p><h2 id="hosting-and-technical-logs" tabindex="-1">Hosting and Technical Logs <a class="header-anchor" href="#hosting-and-technical-logs" aria-label="Permalink to &quot;Hosting and Technical Logs&quot;">​</a></h2><p>AR Blogz is deployed through Cloudflare Pages and GitHub Pages. When you visit, the selected hosting provider can receive your IP address, browser and device details, requested URL, referrer, timestamps, and security or diagnostic information. Each provider handles this information under its own policies and retention practices.</p><h2 id="daily-updates-and-external-requests" tabindex="-1">Daily Updates and External Requests <a class="header-anchor" href="#daily-updates-and-external-requests" aria-label="Permalink to &quot;Daily Updates and External Requests&quot;">​</a></h2><p>The feed can request daily-status content from a public GitHub-hosted JSON source. If direct retrieval fails, it can try the GitHub API, AllOrigins, or a site-hosted fallback. These services receive the requested URL and standard connection metadata.</p><p>Articles can load external scripts, fonts, diagrams, images, video or social-media embeds, and linked resources. Depending on the article, providers such as YouTube, Instagram, GitHub, MathJax or content-delivery networks can receive your IP address, user agent, referrer, cookies or account state, requested content, and interaction information under their own policies.</p><h2 id="analytics-and-comments" tabindex="-1">Analytics and Comments <a class="header-anchor" href="#analytics-and-comments" aria-label="Permalink to &quot;Analytics and Comments&quot;">​</a></h2><p>Google Analytics, Umami, Busuanzi page counting, Giscus, and Waline are supported by the site code but are disabled in the reviewed production configuration. AR Blogz does not currently use them to collect visitor analytics or comments. If any is enabled, this policy and any required consent controls must be updated first.</p><h2 id="search-and-rss" tabindex="-1">Search and RSS <a class="header-anchor" href="#search-and-rss" aria-label="Permalink to &quot;Search and RSS&quot;">​</a></h2><p>Site search runs against the blog&#39;s published search index in your browser. Search text is not submitted to an AR Blogz search server. RSS readers and other clients that request the feed disclose standard connection information to the hosting provider.</p><h2 id="donations-and-external-links" tabindex="-1">Donations and External Links <a class="header-anchor" href="#donations-and-external-links" aria-label="Permalink to &quot;Donations and External Links&quot;">​</a></h2><p>Some articles may display optional donation methods or links to PayPal, Google Pay, GitHub Sponsors, Buy Me a Coffee, Ko-fi, or other services. AR Blogz does not directly process payment-card or bank credentials. The selected payment provider receives and handles the information required for your transaction.</p><p>Social profiles, citations, shopping or product references, and other external links take you to independent services. Their content and privacy practices are outside AR Blogz&#39;s control.</p><h2 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to &quot;Cookies&quot;">​</a></h2><p>AR Blogz does not set its own advertising cookie. Hosting providers, embedded media, payment services, or other third parties may use cookies or similar technology when their resources are loaded or opened. You can manage cookies and site storage through your browser.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Theme, language, and password-access records stay in your browser as described above. Clear the site&#39;s cookies, localStorage, cache, and permissions to remove them.</p><p>Google Form submissions remain with Google and the form owner until deleted or no longer needed, subject to legal or operational requirements. To request access, correction, or deletion of a contact submission, email the address below with enough non-sensitive information to identify it. Hosting or third-party logs must be handled by the relevant provider.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>AR Blogz is a general-audience publication and is not designed to collect personal information from children. A child should not submit the contact form without appropriate parent or guardian involvement.</p><h2 id="changes-and-contact" tabindex="-1">Changes and Contact <a class="header-anchor" href="#changes-and-contact" aria-label="Permalink to &quot;Changes and Contact&quot;">​</a></h2><p>This policy may be updated when site features, providers, or data practices change.</p><ul><li><strong>Publisher:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',34)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
